"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Optimized: O((V+E) log V) using Dijkstra's algorithm with min-heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    pq = [(0, source)]
    visited = set()

    while pq:
        current_dist, u = heapq.heappop(pq)

        if u in visited:
            continue

        visited.add(u)

        # Early termination when target is reached
        if u == target:
            break

        # Skip if we've found a better path already
        if current_dist > dist[u]:
            continue

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = dist[u] + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    if dist[target] == float('inf'):
        return None, []

    # Reconstruct path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Optimized: Single Dijkstra pass — O((V+E) log V).
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    pq = [(0, source)]
    visited = set()

    while pq:
        current_dist, u = heapq.heappop(pq)

        if u in visited:
            continue

        visited.add(u)

        if current_dist > dist[u]:
            continue

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = dist[u] + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    # Build result with paths
    result = {}
    for node in nodes:
        if dist[node] != float('inf'):
            # Reconstruct path
            path = []
            current = node
            while current is not None:
                path.append(current)
                current = prev[current]
            path.reverse()
            result[node] = (dist[node], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Optimized: Early-termination Dijkstra — O((V+E) log V), but can stop after finding k nodes.
    """
    nodes = graph.nodes
    if source not in nodes:
        return []

    dist = {n: float('inf') for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    pq = [(0, source)]
    visited = set()
    result = []

    while pq and len(result) < k:
        current_dist, u = heapq.heappop(pq)

        if u in visited:
            continue

        visited.add(u)

        # Add to result if not source
        if u != source:
            result.append((u, current_dist))
            if len(result) >= k:
                break

        if current_dist > dist[u]:
            continue

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = dist[u] + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Optimized: Simple BFS — O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False

    if source == target:
        return True

    visited = set()
    queue = deque([source])
    visited.add(source)

    while queue:
        u = queue.popleft()

        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Optimized: BFS with undirected edge treatment — O(V + E).
    """
    # Build undirected adjacency list
    undirected_adj: Dict[int, Set[int]] = {node: set() for node in graph.nodes}

    for node in graph.nodes:
        for neighbor, _ in graph.neighbors(node):
            undirected_adj[node].add(neighbor)
            undirected_adj[neighbor].add(node)

    visited = set()
    components = []

    for node in graph.nodes:
        if node in visited:
            continue

        # BFS to find all nodes in this component
        component = set()
        queue = deque([node])
        visited.add(node)
        component.add(node)

        while queue:
            u = queue.popleft()
            for v in undirected_adj[u]:
                if v not in visited:
                    visited.add(v)
                    component.add(v)
                    queue.append(v)

        components.append(component)

    return components
```

**Key optimizations:**

1. **`shortest_path`**: Replaced the O(V·E²) nested loops with Dijkstra's algorithm using a min-heap priority queue. Now O((V+E) log V).

2. **`all_shortest_paths`**: Instead of calling `shortest_path` V times, runs a single Dijkstra pass and reconstructs all paths from the predecessor array. O((V+E) log V).

3. **`k_nearest`**: Uses early-termination Dijkstra that stops after finding k nearest nodes (excluding source). Practically faster than computing all paths.

4. **`is_reachable`**: Replaced expensive shortest path computation with simple BFS that stops as soon as target is found. O(V+E).

5. **`connected_components`**: Replaced O(V²·E²) pairwise reachability checks with a single pass using BFS on an undirected graph representation. O(V+E).

All function signatures, return types, and API contracts are preserved exactly.
